import * as THREE from 'three';

export const LEG_LEN = 2;
export const BODY_HEIGHT = 1.5;

const PHASES = {
  FL: 0,             // front-left  — diagonal pair with BR
  FR: Math.PI,       // front-right — diagonal pair with BL
  BL: Math.PI,       // back-left
  BR: 0,             // back-right
};

/**
 * Build a quadruped rig:
 *   critter.root
 *     └─ body (BoxGeometry mesh)
 *          ├─ hipFL ─ boneFL ─ footTipFL (at (0, -legLen, 0))
 *          ├─ hipFR ─ boneFR ─ ...
 *          ├─ hipBL ─ ...
 *          └─ hipBR ─ ...
 */
export function buildCritter({
  bodySize = [1.6, 0.8, 2.4],
  legLen = LEG_LEN,
} = {}) {
  const root = new THREE.Group();

  const body = new THREE.Mesh(
    new THREE.BoxGeometry(...bodySize),
    new THREE.MeshBasicMaterial({ color: 0x888888 })
  );
  // Lift the body so the straight legs reach y = -legLen in world space.
  body.position.y = BODY_HEIGHT;
  root.add(body);

  const [w, , d] = bodySize;
  const hips = {};
  const bones = {};
  const footTips = {};

  const corners = [
    ['FL', w / 4, -d / 4],
    ['FR', w / 4, d / 4],
    ['BL', -w / 4, -d / 4],
    ['BR', -w / 4, d / 4],
  ];

  for (const [name, x, z] of corners) {
    const hip = new THREE.Group();
    hip.name = `hip${name}`;
    hip.position.set(x, -bodySize[1] / 2, z); // hang from bottom edge of body
    body.add(hip);

    const bone = new THREE.Bone();
    bone.name = `bone${name}`;
    hip.add(bone);

    const tip = new THREE.Object3D(); // foot tip marker
    tip.name = `tip${name}`;
    tip.position.set(0, -legLen, 0);
    bone.add(tip);

    hips[name] = hip;
    bones[name] = bone;
    footTips[name] = tip;
  }

  return { root, body, hips, bones, footTips, phases: { ...PHASES }, legLen };
}

/**
 * Diagonal-gait walk cycle: each hip swings about its local X axis.
 * rotation.x = amp * sin(2π·freq·t + phase), phases FL=BR=0, FR=BL=π.
 */
export function poseWalk(critter, t, { freq = 2, amp = 0.5 } = {}) {
  for (const name of Object.keys(critter.hips)) {
    const phase = critter.phases[name] ?? PHASES[name];
    critter.hips[name].rotation.x =
      amp * Math.sin(2 * Math.PI * freq * t + phase);
  }
}

/** Update all world matrices so getWorldPosition reads are valid. */
export function updateWorld(critter) {
  critter.root.updateMatrixWorld(true);
}

