import { describe, it, expect } from 'vitest';
import { buildCritter, poseWalk, updateWorld, LEG_LEN, BODY_HEIGHT } from '../src/critter.js';

const NAMES = ['FL', 'FR', 'BL', 'BR'];
const FREQ = 2;
const AMP = 0.5;
const TOL = 1e-9;

/** Pose the critter at time t and return each hip's rotation.x. */
function hipAnglesAt(critter, t) {
  poseWalk(critter, t, { freq: FREQ, amp: AMP });
  return Object.fromEntries(NAMES.map((n) => [n, critter.hips[n].rotation.x]));
}

describe('critter walk cycle', () => {
  it('builds a rig with four hips, bones and foot tips', () => {
    const c = buildCritter();
    for (const n of NAMES) {
      expect(c.hips[n]).toBeDefined();
      expect(c.bones[n]).toBeDefined();
      expect(c.bones[n].isBone).toBe(true);
      expect(c.footTips[n]).toBeDefined();
      expect(c.bones[n].position.y).toBe(0);
      expect(c.footTips[n].position.y).toBe(-LEG_LEN);
    }
  });

  it('at t = 1/(4*freq), FL/BR are at +amp and FR/BL are at -amp', () => {
    const c = buildCritter();
    const t = 1 / (4 * FREQ); // sin(2π·freq·t) = sin(π/2) = 1
    const a = hipAnglesAt(c, t);
    expect(Math.abs(a.FL - AMP)).toBeLessThan(TOL);
    expect(Math.abs(a.BR - AMP)).toBeLessThan(TOL);
    expect(Math.abs(a.FR + AMP)).toBeLessThan(TOL);
    expect(Math.abs(a.BL + AMP)).toBeLessThan(TOL);
  });

  it('diagonal pairs (FL,BR) and (FR,BL) stay equal for random times', () => {
    const c = buildCritter();
    for (let i = 0; i < 25; i++) {
      const t = Math.random() * 10;
      const a = hipAnglesAt(c, t);
      expect(Math.abs(a.FL - a.BR)).toBeLessThan(TOL);
      expect(Math.abs(a.FR - a.BL)).toBeLessThan(TOL);
    }
  });

  it('opposite pairs stay negated for random times', () => {
    const c = buildCritter();
    for (let i = 0; i < 25; i++) {
      const t = Math.random() * 10;
      const a = hipAnglesAt(c, t);
      expect(Math.abs(a.FL + a.FR)).toBeLessThan(TOL);
      expect(Math.abs(a.FL + a.BL)).toBeLessThan(TOL);
      expect(Math.abs(a.BR + a.FR)).toBeLessThan(TOL);
      expect(Math.abs(a.BR + a.BL)).toBeLessThan(TOL);
    }
  });

  it('the cycle repeats with period 1/freq', () => {
    const c = buildCritter();
    const period = 1 / FREQ;
    for (let i = 0; i < 25; i++) {
      const t = Math.random() * 50;
      const a1 = hipAnglesAt(c, t);
      const a2 = hipAnglesAt(c, t + period);
      for (const n of NAMES) {
        // compare via wrapped difference to dodge float noise in large args
        let d = a2[n] - a1[n];
        if (d > Math.PI) d -= 2 * Math.PI;
        if (d < -Math.PI) d += 2 * Math.PI;
        expect(Math.abs(d)).toBeLessThan(1e-6);
      }
    }
    // exact check at small t where floats behave
    const b = hipAnglesAt(buildCritter(), 0.3);
    const c2 = hipAnglesAt(buildCritter(), 0.3 + period);
    for (const n of NAMES) expect(Math.abs(c2[n] - b[n])).toBeLessThan(TOL);
  });

  it('all foot tips stay above y = -legLen - bodyHeight for all sampled t', () => {
    const c = buildCritter();
    updateWorld(c); // ensure world matrices exist before sampling
    const floorY = -LEG_LEN - BODY_HEIGHT;
    const steps = 400;
    for (let i = 0; i <= steps; i++) {
      const t = (i / steps) * (2 / FREQ); // two full cycles
      poseWalk(c, t, { freq: FREQ, amp: AMP });
      updateWorld(c);
      for (const n of NAMES) {
        const p = new THREE.Vector3();
        c.footTips[n].getWorldPosition(p);
        expect(p.y).toBeGreaterThanOrEqual(floorY);
      }
    }
  });
});

